'use strict';
const $=s=>document.querySelector(s);
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>',work:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1zM9 21v-8h6v8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M16 13h5M16 16h5"/>',chart:'<path d="M4 3v18h17M8 16v-5M13 16V6M18 16V9"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',leaf:'<path d="M20 3c-2 0-13-1-15 8s8 12 12 5 3-13 3-13ZM4 21 16 9"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(Number(n)||0);
const date=d=>new Intl.DateTimeFormat('pt-PT',{day:'2-digit',month:'short'}).format(new Date(d+'T12:00:00'));
const round=n=>Math.round((n+Number.EPSILON)*100)/100;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const seedV1=()=>({employees:[{id:'e1',name:'António Ferreira',category:'Oficial',rate:85,access:'Encarregado',active:true},{id:'e2',name:'João Martins',category:'Ajudante',rate:55,access:'Colaborador',active:true},{id:'e3',name:'Miguel Santos',category:'Eletricista',rate:95,access:'Colaborador',active:true},{id:'e4',name:'Pedro Costa',category:'Canalizador',rate:90,access:'Colaborador',active:true},{id:'e5',name:'Rui Almeida',category:'Ajudante',rate:55,access:'Colaborador',active:true}],clients:[{id:'c1',name:'Maria Oliveira',city:'Maia',cycle:'Semanal'},{id:'c2',name:'Carlos Pereira',city:'Porto',cycle:'Mensal'},{id:'c3',name:'Ana Rodrigues',city:'Matosinhos',cycle:'Semanal'},{id:'c4',name:'Condomínio das Flores',city:'Gondomar',cycle:'Mensal'}],projects:[{id:'o1',name:'Remodelação de apartamento',client:'c1',status:'Em curso',progress:65,budget:12500},{id:'o2',name:'Renovação de casa de banho',client:'c2',status:'Em curso',progress:40,budget:4800},{id:'o3',name:'Pintura de moradia',client:'c3',status:'Em curso',progress:85,budget:3200},{id:'o4',name:'Reabilitação de fachada',client:'c4',status:'Planeada',progress:0,budget:8900}],entries:[{id:'r1',employee:'e1',project:'o1',date:'2026-10-12',days:1,rate:85,note:'Preparação de paredes'},{id:'r2',employee:'e2',project:'o1',date:'2026-10-12',days:1,rate:55,note:'Apoio em obra'},{id:'r3',employee:'e3',project:'o2',date:'2026-10-13',days:1,rate:95,note:'Instalação elétrica'},{id:'r4',employee:'e4',project:'o2',date:'2026-10-14',days:1,rate:90,note:'Substituição da canalização'},{id:'r5',employee:'e1',project:'o1',date:'2026-10-15',days:1,rate:85,note:'Assentamento de revestimento'},{id:'r6',employee:'e5',project:'o3',date:'2026-10-15',days:.5,rate:55,note:'Preparação para pintura'}],charges:[{id:'p1',client:'c1',project:'o1',amount:1250,due:'2026-10-16',period:'12–16 out.',paid:0},{id:'p2',client:'c3',project:'o3',amount:800,due:'2026-10-16',period:'12–16 out.',paid:300},{id:'p3',client:'c2',project:'o2',amount:1600,due:'2026-10-31',period:'Outubro 2026',paid:0},{id:'p4',client:'c4',project:'o4',amount:1000,due:'2026-10-31',period:'Adiantamento',paid:1000}],receipts:[{id:'t1',charge:'p2',amount:300,date:'2026-10-15',method:'Transferência'},{id:'t2',charge:'p4',amount:1000,date:'2026-10-14',method:'Transferência'}],activity:[{text:'Registo de trabalho de Rui Almeida adicionado.',date:'2026-10-15'},{text:'Pagamento de Ana Rodrigues registado: 300,00 €.',date:'2026-10-15'},{text:'Reabilitação de fachada adicionada às obras.',date:'2026-10-14'}]});
const seed=()=>{const data=seedV1();data.wagePayments=[{id:'w1',employee:'e1',amount:100,date:'2026-10-14',type:'advance',method:'Transferência',note:'Adiantamento de exemplo'}];data.entries.push({id:'r7',employee:'e2',project:'o1',date:'2026-10-16',days:.5,rate:55,note:'Preparação de materiais · aguarda validação',status:'pending'});return LinoModel.migrate(data);};
const KEY='lino-gestao-demo-v1';let storageOK=true;let db;
try{db=JSON.parse(localStorage.getItem(KEY));if(!db||!['employees','clients','projects','entries','charges','receipts','activity'].every(k=>Array.isArray(db[k])))db=seed()}catch{db=seed();storageOK=false}
db=LinoModel.migrate(db);
let role='admin',query='',filter='',page='',period='Semanal';
const routes=[['resumo','Visão geral','grid'],['equipa','Equipa','team'],['clientes','Clientes','team'],['obras','Obras','work'],['registos','Registos de trabalho','clock'],['salarios','Pagamentos à equipa','team'],['pagamentos','Recebimentos','wallet'],['relatorios','Relatórios','chart']];
const employee=id=>db.employees.find(e=>e.id===id);const project=id=>db.projects.find(e=>e.id===id);const client=id=>db.clients.find(e=>e.id===id);
const visibleEntries=()=>role==='worker'?db.entries.filter(e=>e.employee==='e2'):db.entries;
const canFinance=()=>role==='admin';
const balance=p=>round(p.amount-p.paid);const id=()=>crypto.randomUUID();
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function save(text){if(text)db.activity.unshift({text,date:today()});db.activity=db.activity.slice(0,15);try{localStorage.setItem(KEY,JSON.stringify(db))}catch{storageOK=false;toast('Sem acesso ao armazenamento. As alterações duram apenas nesta sessão.')}render();if(storageOK&&text)toast('Alteração guardada nesta demonstração.');}
const badge=(s,c='')=>`<span class="badge ${c}">${esc(s)}</span>`;
const initials=n=>n.split(' ').map(s=>s[0]).slice(0,2).join('');
const button=(label,action,primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${esc(label)}</button>`;
function heading(title,subtitle,actions=''){return `<section class="page-heading"><div><span class="eyebrow">A SUA OPERAÇÃO, NUM SÓ LUGAR</span><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></section>`}
function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`}
function table(headers,rows,empty='Sem resultados para mostrar.'){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}"><div class="empty">${empty}</div></td></tr>`}</tbody></table></div>`}
function stat(title,value,note,i){return `<div class="stat"><div class="stat-top">${title}<span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function tool(placeholder,options=''){return `<div class="toolbar"><input class="search" id="search" aria-label="Pesquisar" placeholder="${placeholder}" value="${esc(query)}">${options}</div>`}
function projectRows(list,compact=false){return list.map(o=>`<tr ${compact?'class="clickable" data-action="goto-obras"':''}><td><div class="project-name"><span class="project-icon">${icon('work')}</span><div><strong>${esc(o.name)}</strong><small>${esc(client(o.client)?.name)} · ${esc(client(o.client)?.city)}</small></div></div></td><td>${badge(o.status,o.status==='Planeada'?'amber':o.status==='Concluída'?'gray':'')}</td><td><div class="progress"><span style="width:${Math.min(100,Math.max(0,o.progress))}%"></span></div><span class="progress-label">${o.progress}% concluído</span></td>${!compact?`<td>${canFinance()?euro(o.budget):'—'}</td><td>${role!=='worker'?`<button class="btn small" data-action="edit-project" data-id="${o.id}">Editar</button>`:''}</td>`:''}</tr>`)}
function clients(){const list=db.clients.filter(c=>`${c.name} ${c.city}`.toLowerCase().includes(query.toLowerCase()));return heading('Clientes','Contactos de obra e periodicidade dos pagamentos.',canFinance()?button('+ Adicionar cliente','new-client',true):'')+panel('Carteira de clientes','Cada cliente pode ter uma periodicidade diferente.',tool('Pesquisar cliente ou localidade…')+table(['Cliente','Localidade','Periodicidade','Obras',...(canFinance()?['Por receber','Ações']:[])],list.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.city)}</td><td>${badge(c.cycle,c.cycle==='Semanal'?'':'amber')}</td><td>${db.projects.filter(o=>o.client===c.id).length}</td>${canFinance()?`<td>${euro(db.charges.filter(p=>p.client===c.id).reduce((a,p)=>a+balance(p),0))}</td><td><button class="btn small" data-action="edit-client" data-id="${c.id}">Editar</button></td>`:''}</tr>`)))}
function works(){const list=db.projects.filter(o=>`${o.name} ${client(o.client)?.name}`.toLowerCase().includes(query.toLowerCase())&&(!filter||o.status===filter));return heading('Obras em boas mãos','Planeie, acompanhe e organize cada projeto.',role!=='worker'?button('+ Nova obra','new-project',true):'')+panel('Todas as obras','Da primeira visita à entrega.',tool('Pesquisar obra ou cliente…',`<select id="filter" aria-label="Filtrar estado"><option value="">Todos os estados</option>${['Planeada','Em curso','Concluída'].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select>`)+table(['Obra / cliente','Estado','Progresso',canFinance()?'Valor acordado':'Valor','Ações'],projectRows(list)))}
function payments(){const list=db.charges.filter(p=>client(p.client)?.cycle===period&&`${client(p.client)?.name} ${project(p.project)?.name}`.toLowerCase().includes(query.toLowerCase()));const pending=db.charges.reduce((a,p)=>a+balance(p),0);return heading('Pagamentos sob controlo','Acompanhe valores acordados, recebimentos e saldos pendentes.',button('+ Nova cobrança','new-charge',true))+`<section class="stats">${stat('Total a receber',euro(pending),'Saldo de todas as cobranças','wallet')}${stat('Recebido',euro(db.receipts.reduce((a,p)=>a+p.amount,0)),'Pagamentos efetivamente registados','check')}${stat('Clientes semanais',db.clients.filter(c=>c.cycle==='Semanal').length,'Periodicidade semanal','calendar')}${stat('Clientes mensais',db.clients.filter(c=>c.cycle==='Mensal').length,'Periodicidade mensal','calendar')}</section><div class="notice">Controlo interno de cobranças. Os valores são introduzidos manualmente e não constituem faturas nem são calculados automaticamente a partir da remuneração dos funcionários.</div>`+panel('Cobranças por periodicidade','Consulte o valor total, o que já recebeu e o saldo.',`<div class="toolbar"><div class="tabs">${['Semanal','Mensal'].map(p=>`<button class="btn ${period===p?'selected':''}" data-action="period" data-id="${p}">${p==='Semanal'?'Semanais':'Mensais'}</button>`).join('')}</div><input class="search" id="search" aria-label="Pesquisar cobranças" placeholder="Pesquisar cliente ou obra…" value="${esc(query)}"></div>`+table(['Cliente / obra','Vencimento','Total','Recebido','Por receber','Estado','Ações'],list.map(p=>`<tr><td><strong>${esc(client(p.client)?.name)}</strong><small>${esc(project(p.project)?.name)} · ${esc(p.period)}</small></td><td>${date(p.due)}</td><td>${euro(p.amount)}</td><td>${euro(p.paid)}</td><td><strong>${euro(balance(p))}</strong></td><td>${badge(balance(p)<=0?'Liquidado':p.paid?'Parcial':'Pendente',balance(p)<=0?'':p.paid?'amber':'red')}</td><td>${balance(p)>0?`<button class="btn small" data-action="receive" data-id="${p.id}">Registar pagamento</button>`:'—'}</td></tr>`)))+panel('Histórico de recebimentos','Registos guardados nesta demonstração.',table(['Data','Cliente','Valor','Método'],[...db.receipts].reverse().map(r=>`<tr><td>${date(r.date)}</td><td>${esc(client(db.charges.find(p=>p.id===r.charge)?.client)?.name)}</td><td>${euro(r.amount)}</td><td>${esc(r.method)}</td></tr>`))).replace('class="panel"','class="panel activity-panel"')}
function allowed(route){if(route==='salarios'&&role==='manager')return false;return !(['pagamentos','relatorios'].includes(route)&&!canFinance())&&!(role==='worker'&&['equipa','clientes'].includes(route))}
function render(){db=LinoModel.migrate(db);let next=location.hash.slice(1)||'resumo';if(!routes.some(r=>r[0]===next)||!allowed(next))next='resumo';if(next!==page){query='';filter='';page=next}$('#breadcrumb').textContent=routes.find(r=>r[0]===page)[1];$('#navigation').innerHTML=routes.filter(r=>allowed(r[0])).map(([key,label,i])=>`<a href="#${key}" class="${key===page?'active':''}" ${key===page?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('');$('#app').innerHTML=({resumo:summary,equipa:team,clientes:clients,obras:works,registos:entries,pagamentos:payments,relatorios:reports,salarios:payroll}[page])()+`<p class="storage-note">Demonstração com dados fictícios · ${storageOK?'Alterações guardadas apenas neste navegador.':'Armazenamento indisponível; alterações apenas nesta sessão.'} Perfis simulados, sem autenticação real.</p>`;const search=$('#search');if(search)search.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)});$('#filter')?.addEventListener('change',e=>{filter=e.target.value;render()})}
const field=(name,label,value='',type='text',attrs='',full=false)=>`<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(name,label,items,value,full=false)=>`<label class="field ${full?'full':''}">${label}<select name="${name}" aria-label="${label}" required>${items.map(i=>{const [v,l]=Array.isArray(i)?i:[i,i];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
function openForm(title,fields,submit,help=''){const form=$('#form');form.oninput=null;form.onchange=null;$('#modal-title').textContent=title;form.innerHTML=`<div class="form-grid">${fields}</div>${help?`<p class="form-help">${help}</p>`:''}<div class="form-actions"><button type="button" class="btn" data-action="cancel">Cancelar</button><button class="btn primary" type="submit">Guardar</button></div>`;form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));try{if(submit(data)!==false)$('#modal').close()}catch(err){toast(err.message||'Não foi possível guardar.')}};$('#modal').showModal()}
function clientForm(c){if(!canFinance())return;openForm(c?'Editar cliente':'Adicionar cliente',field('name','Nome do cliente',c?.name,'text','required maxlength="100"',true)+field('city','Localidade',c?.city,'text','required maxlength="100"')+select('cycle','Periodicidade de pagamento',['Semanal','Mensal'],c?.cycle||'Semanal'),d=>{if(!d.name.trim()||!d.city.trim())throw Error('Preencha nome e localidade.');const data={name:d.name.trim(),city:d.city.trim(),cycle:d.cycle};if(c)Object.assign(c,data);else db.clients.push({id:id(),...data});save(`${data.name}: cliente ${c?'atualizado':'adicionado'}.`);});}
function projectForm(o){if(role==='worker')return;if(!db.clients.length)return toast('Adicione primeiro um cliente.');openForm(o?'Editar obra':'Nova obra',field('name','Nome da obra',o?.name,'text','required maxlength="120"',true)+select('client','Cliente',db.clients.map(c=>[c.id,c.name]),o?.client,true)+select('status','Estado',['Planeada','Em curso','Concluída'],o?.status||'Planeada')+field('progress','Progresso (%)',o?.progress??0,'number','required min="0" max="100" step="1"')+(canFinance()?field('budget','Valor acordado (€)',o?.budget??0,'number','required min="0" max="10000000" step="0.01"',true):''),d=>{if(!d.name.trim())throw Error('Preencha o nome da obra.');const data={name:d.name.trim(),client:d.client,status:d.status,progress:d.status==='Concluída'?100:Number(d.progress),budget:canFinance()?Number(d.budget):(o?.budget??0)};if(o)Object.assign(o,data);else db.projects.push({id:id(),...data});save(`${data.name}: obra ${o?'atualizada':'criada'}.`);});}
function chargeForm(){if(!canFinance())return;if(!db.projects.length)return toast('Adicione primeiro uma obra.');openForm('Nova cobrança',select('project','Obra / cliente',db.projects.map(o=>[o.id,`${o.name} · ${client(o.client)?.name}`]),null,true)+field('amount','Valor a cobrar (€)','','number','required min="0.01" max="10000000" step="0.01"')+field('due','Data de vencimento',today(),'date','required')+field('period','Período / referência','','text','required maxlength="100"',true),d=>{const o=project(d.project);db.charges.push({id:id(),client:o.client,project:o.id,amount:round(Number(d.amount)),due:d.due,period:d.period.trim(),paid:0});period=client(o.client).cycle;save(`Cobrança de ${euro(d.amount)} adicionada para ${client(o.client).name}.`);},'Registo interno de valor acordado com o cliente. Não emite uma fatura.');}
function receive(p){if(!canFinance())return;openForm('Registar pagamento',`<div class="field full"><strong>${esc(client(p.client)?.name)}</strong><span>Saldo pendente: ${euro(balance(p))}</span></div>`+field('amount','Valor recebido (€)',balance(p),'number',`required min="0.01" max="${balance(p)}" step="0.01"`)+field('date','Data do recebimento',today(),'date','required')+select('method','Método de pagamento',['Transferência','Numerário','MB WAY','Outro'],null,true),d=>{const amount=round(Number(d.amount));if(!Number.isFinite(amount)||amount<=0||amount>balance(p))throw Error('O pagamento deve ser superior a zero e não pode exceder o saldo.');p.paid=round(p.paid+amount);db.receipts.push({id:id(),charge:p.id,amount,date:d.date,method:d.method});save(`Pagamento de ${client(p.client)?.name} registado: ${euro(amount)}.`);});}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const key=el.dataset.id;switch(el.dataset.action){case'goto-obras':location.hash='obras';break;case'new-employee':employeeForm();break;case'edit-employee':employeeForm(employee(key));break;case'toggle-employee':if(role==='admin'){const e=employee(key);e.active=!e.active;save(`${e.name}: estado atualizado.`)}break;case'new-client':clientForm();break;case'edit-client':clientForm(client(key));break;case'new-project':projectForm();break;case'edit-project':projectForm(project(key));break;case'new-entry':entryForm();break;case'edit-entry':entryForm(db.entries.find(r=>r.id===key));break;case'new-charge':chargeForm();break;case'receive':receive(db.charges.find(p=>p.id===key));break;case'period':period=key;query='';render();break;case'cancel':$('#modal').close();break;case'export':exportCSV();break}});
$('#role').addEventListener('change',e=>{role=e.target.value;$('#profile-avatar').textContent=role==='worker'?'JM':role==='manager'?'AF':'LR';$('#modal').close();query='';filter='';page='';render();toast('Perfil de demonstração alterado. Não é uma sessão autenticada.');});
$('#close-modal').onclick=()=>$('#modal').close();
$('#reset').onclick=()=>{if(confirm('Repor os dados fictícios? As alterações feitas nesta demonstração serão removidas.')){db=seed();query='';filter='';save();toast('Demonstração reposta.')}};
window.addEventListener('hashchange',render);
